package com.hax.focusdeck
import org.junit.Test
import org.junit.Assert.*
import java.time.Instant
import java.time.ZoneId

class IndexTrackerTest {
    private val zone = ZoneId.of("Europe/Berlin")
    private val now = Instant.parse("2026-10-08T12:00:00Z").toEpochMilli()
    private val doc = IndexDocument(listOf(IndexTopic("1","Chapter"),IndexTopic("1.1","A","1"),IndexTopic("1.2","B","1")))
    private fun base() = AchievementEngine.seed(now,zone)
    private fun create(config: String = "HYBRID") = AchievementEngine.apply(base(),AchievementCommand(5,"index_create","create",Instant.ofEpochMilli(now).toString(),definition=AchievementDefinition("subject","Subject","index","daily"),document=doc,configuration=config),now,zone)
    private fun topic(s: AchievementStore, id: String, done: Boolean, receipt: String, time: Long = now): AchievementCommand = AchievementCommand(5,"index_topic",receipt,Instant.ofEpochMilli(time).toString(),achievement_id="subject",topic_id=id,completed=done,expected_index_revision=s.indexes.getValue("subject").revision)
    private fun apply(s: AchievementStore,c: AchievementCommand) = AchievementEngine.apply(s,c,now,zone)
    private fun rejects(block: () -> Unit) { try { block();fail("Expected rejection") } catch(e: IllegalArgumentException) {} }
    @Test fun importCountsOnlyUniqueLeaves() { val s=create();assertEquals(2,s.indexes.getValue("subject").leaves().size);assertEquals(0.0,s.definitions.last().progress!!.currentValue,0.0) }
    @Test fun duplicateAndAmbiguousNumbersRejected() { rejects { IndexTracker.validate(IndexDocument(listOf(IndexTopic("1","A"),IndexTopic("1","B")))) };rejects { IndexTracker.validate(IndexDocument(listOf(IndexTopic("1","A"),IndexTopic("01","B")))) } }
    @Test fun missingParentAndCycleRejected() { rejects { IndexTracker.validate(IndexDocument(listOf(IndexTopic("1.1","A","1")))) };rejects { IndexTracker.validate(IndexDocument(listOf(IndexTopic("a","A","b"),IndexTopic("b","B","a")))) } }
    @Test fun completeReopenRecompleteKeepEvidenceAndExactReceipt() { var s=create();val first=topic(s,"1.1",true,"one");s=apply(s,first);assertEquals(s,apply(s,first));s=apply(s,topic(s,"1.1",true,"noop"));assertEquals(1,s.indexes.getValue("subject").events.size);s=apply(s,topic(s,"1.1",false,"reopen"));assertEquals(0,s.indexes.getValue("subject").completed());s=apply(s,topic(s,"1.1",true,"again"));val l=s.indexes.getValue("subject");assertEquals(listOf(1,-1,1),l.events.map{it.delta});assertEquals(1,l.completed());assertEquals(2,l.events.count{it.delta>0});assertEquals(1,l.events.sumOf{it.delta}) }
    @Test fun topicDoesNotManufactureStudyDay() { var s=create();s=apply(s,topic(s,"1.1",true,"one"));assertEquals(0L,s.days[AchievementEngine.date(now,zone)]?.activities?.get("subject")?:0L);s=apply(s,AchievementCommand(5,"event","study",Instant.ofEpochMilli(now).toString(),achievement_id="subject",event="completed"));assertEquals(1,s.indexes.getValue("subject").completed());assertEquals(1L,s.days.getValue(AchievementEngine.date(now,zone)).activities["subject"]);assertTrue(s.indexes.getValue("subject").milestones.any{it.title.startsWith("Verified daily")}) }
    @Test fun progressOnlyHasNoStreak() { val s=create("PROGRESS_ONLY");assertFalse(s.definitions.last().streakEnabled);rejects { apply(s,AchievementCommand(5,"event","bad",Instant.ofEpochMilli(now).toString(),achievement_id="subject",event="completed")) } }
    @Test fun numericalProgressAndStaleRevisionRejected() { val s=create();rejects{apply(s,AchievementCommand(5,"progress_set","bad",Instant.ofEpochMilli(now).toString(),achievement_id="subject",current_value=100.0))};rejects{apply(s,topic(s,"1.1",true,"bad").copy(expected_index_revision=0))} }
    @Test fun renamingRemovingAndRestoringPreserveIdentityAndHistory() { var s=create();s=apply(s,topic(s,"1.1",true,"one"));fun revision(d: IndexDocument,id:String){s=apply(s,AchievementCommand(5,"index_reconcile",id,Instant.ofEpochMilli(now).toString(),achievement_id="subject",document=d,expected_index_revision=s.indexes.getValue("subject").revision,confirm=true))};revision(IndexDocument(listOf(IndexTopic("1","Chapter"),IndexTopic("1.2","Renamed","1"))),"remove");assertEquals(0,s.indexes.getValue("subject").completed());assertEquals(1,s.indexes.getValue("subject").events.size);revision(doc,"restore");assertEquals(1,s.indexes.getValue("subject").completed());assertEquals(3,s.indexes.getValue("subject").revisions.size) }
    @Test fun explicitMigrationRetainsLegacyNumericIdentity() { val old=base().copy(definitions=base().definitions.map{if(it.id=="custom_compute")it.copy(progress=AchievementProgress(23.0,126.0,"index topics")) else it});val c=AchievementCommand(5,"index_migrate","migration",Instant.ofEpochMilli(now).toString(),achievement_id="custom_compute",document=doc,expected_store_revision=old.revision,confirm=true);val s=apply(old,c);assertEquals(23.0,s.indexes.getValue("custom_compute").originalDefinition!!.progress!!.currentValue,0.0);assertEquals(0,s.indexes.getValue("custom_compute").completed());assertEquals(old.definitions.size,s.definitions.size);assertEquals("scheduled",s.definitions.last().kind);assertEquals(s,apply(s,c));rejects{apply(old,c.copy(confirm=false))} }
    @Test fun milestonesAreDerivedAndReplaySafe() { var s=create();s=apply(s,topic(s,"1.1",true,"one"));val c=topic(s,"1.2",true,"two");s=apply(s,c);assertEquals(s,apply(s,c));assertTrue(s.indexes.getValue("subject").milestones.any{it.title=="Section 1 fully completed"});assertTrue(s.indexes.getValue("subject").milestones.any{it.title=="100% of Index completed"}) }
    @Test fun lateDistinctTopicEvidenceUsesActualPhoneDate() { var s=create();s=apply(s,topic(s,"1.1",true,"first"));s=apply(s,topic(s,"1.2",true,"second",now-86400000));assertEquals(AchievementEngine.date(now-86400000,zone),s.indexes.getValue("subject").events.last().date) }
}
